    if (t.why) text += `Why: ${t.why}\n`;
    if (t.url) text += `Watch: ${t.url}\n`;
    text += `\n--------------------------\n\n`;
  });

  text += `\nReachAI — Smarter YouTube Growth\n`;
  return text;
}









